ng:58px 0}.section-head{max-width:650px;margin-bottom:28px}.section-head h2{font-size:clamp(28px,4vw,40px);letter-spacing:-.04em;line-height:1.15;margin:0 0 12px}.section-head p,.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.feature{padding:22px;border:1px solid var(--line);border-radius:12px;background:#fff}.feature .icon{font-size:25px}.feature h3{margin:12px 0 5px;font-size:18px}.feature p{margin:0;color:var(--muted)}.band{background:var(--mint)}.band-row{display:flex;justify-content:space-between;align-items:center;gap:24px}.band h2{font-size:32px;line-height:1.15;letter-spacing:-.04em;margin:0 0 8px}.band p{margin:0;color:var(--muted)}footer{padding:28px 0;color:var(--muted);font-size:14px;border-top:1px solid var(--line)}@media(max-width:760px){.nav{height:auto;min-height:72px}.navlinks{gap:10px}.navlinks .hide-small{display:none}.hero{padding:48px 0}.hero-grid{grid-template-columns:1fr;gap:24px}.grid{grid-template-columns:1fr}.band-row{align-items:flex-start;flex-direction:column}section{padding:42px 0}}
